/**
 * Writes the inspectors' copies of plugin tables as plain scripts (the
 * inspectors are file:// pages without a bundler or fetch):
 *   ui/preset-captions.js  the bundled profiles' captions (src/obs/preset-captions.ts)
 * Run: node --import tsx scripts/generate-ui-i18n.ts
 * tests/preset-captions.test.ts fails when a generated file is out of date.
 */
import { writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { PRESET_CAPTIONS } from "../src/obs/preset-captions.js";

export const UI_DIR = resolve(process.cwd(), "com.jbrick2070.fadester-for-obs.sdPlugin/ui");

const HEADER = [
  "// SPDX-License-Identifier: GPL-2.0-or-later",
  "// Generated by scripts/generate-ui-i18n.ts; edit the source table, not this file."
];

export function presetCaptionsScript(): string {
  const captions = Object.fromEntries(Object.entries(PRESET_CAPTIONS).map(([action, contexts]) => [action,
    Object.fromEntries(Object.entries(contexts).map(([context, entry]) =>
      [context, [...entry.shipped, ...entry.legacy].map((caption) => caption.toLowerCase())]))]));
  return [
    ...HEADER,
    "// The bundled profiles' English captions (src/obs/preset-captions.ts): a stored caption",
    "// equal to one of them, in its context, is a generated default, never a saved custom label.",
    "(function () {",
    "  \"use strict\";",
    `  var CAPTIONS = ${JSON.stringify(captions)};`,
    "  var AUTOMATIC_INPUT = /^__audio_(main|mic|aux|input_\\d+)__$/;",
    "  function text(settings, key) {",
    "    var value = settings ? settings[key] : undefined;",
    "    return typeof value === \"string\" ? value.trim() : \"\";",
    "  }",
    "  function context(action, settings) {",
    "    if (action === \"scene\") return text(settings, \"sceneTarget\");",
    "    if (action === \"fader\") {",
    "      if (text(settings, \"target\") === \"tbar\") return \"tbar\";",
    "      return AUTOMATIC_INPUT.test(text(settings, \"inputName\")) ? \"automaticInput\" : \"\";",
    "    }",
    "    if (action === \"fade\") return AUTOMATIC_INPUT.test(text(settings, \"inputName\")) ? \"automaticInput\" : \"\";",
    "    if (action === \"layerKey\") return text(settings, \"operation\") || \"select_next\";",
    "    if (action === \"layerDial\") return text(settings, \"dialMode\") || \"select_layer\";",
    "    return \"\";",
    "  }",
    "  function isGenerated(action, settings, caption) {",
    "    var raw = caption === undefined ? (settings ? settings.labelOverride : undefined) : caption;",
    "    if (typeof raw !== \"string\") return false;",
    "    var normalized = raw.trim().replace(/\\s+/g, \" \").toLowerCase();",
    "    var known = CAPTIONS[action] && CAPTIONS[action][context(action, settings)];",
    "    return Boolean(normalized && known && known.indexOf(normalized) !== -1);",
    "  }",
    "  window.FadesterPresetCaptions = { isGenerated: isGenerated };",
    "})();",
    ""
  ].join("\n");
}

function main(): void {
  writeFileSync(resolve(UI_DIR, "preset-captions.js"), presetCaptionsScript());
  console.log("Wrote ui/preset-captions.js");
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) main();
